/*
 * Compass header interactions (same state classes as scotiabank.com): bound on the compass markup
 * (AEM header component variant "compass", or blocks/header/compass.js for EDS documents).
 * Self-contained: also shipped in the AEM clientlib (aem-scotia clientlib-site js/compass.js,
 * generated by tools/sync-from-eds.mjs).
 */

const SEARCH_URL = 'https://www.scotiabank.com/ca/en/search-results.html';

const search = (q) => {
  window.location.href = `${SEARCH_URL}${q ? `?q=${encodeURIComponent(q)}` : ''}`;
};

/** toggle-submenu buttons: aria-expanded + "active" on the submenu they control */
function submenuOf(button) {
  const li = button.closest('li, .site-nav');
  return li?.querySelector(':scope > .submenu-wrapper > ul, :scope > nav > ul');
}

function setOpen(button, open) {
  button.setAttribute('aria-expanded', open ? 'true' : 'false');
  submenuOf(button)?.classList.toggle('active', open);
}

function initMenus(root) {
  // top level (site nav "More Sites" + mega-menu categories): one open at a time
  const top = [root.querySelector('.site-nav > button.toggle-submenu'),
    ...root.querySelectorAll('#mega-menu > ul > li > button.toggle-submenu')].filter(Boolean);
  const closeTop = (except) => top.filter((b) => b !== except).forEach((b) => setOpen(b, false));
  top.forEach((b) => b.addEventListener('click', () => {
    const open = b.getAttribute('aria-expanded') !== 'true';
    closeTop(b);
    setOpen(b, open);
  }));
  // mega-menu sections (mobile accordion)
  root.querySelectorAll('#mega-menu .submenu > li > button.toggle-submenu').forEach((b) => {
    b.addEventListener('click', () => setOpen(b, b.getAttribute('aria-expanded') !== 'true'));
  });
  // language menu
  const lang = root.querySelector('#language-toggle');
  const langMenu = root.querySelector('#language-menu');
  const setLang = (open) => {
    lang?.setAttribute('aria-expanded', open ? 'true' : 'false');
    langMenu?.classList.toggle('active', open);
  };
  lang?.addEventListener('click', () => setLang(lang.getAttribute('aria-expanded') !== 'true'));

  document.addEventListener('keydown', (e) => {
    if (e.key !== 'Escape') return;
    closeTop();
    setLang(false);
  });
  document.addEventListener('click', (e) => {
    if (!root.querySelector('#mega-menu')?.contains(e.target) && !root.querySelector('.site-nav')?.contains(e.target)) closeTop();
    if (!root.querySelector('.lang-nav')?.contains(e.target)) setLang(false);
  });
}

function initSearch(root) {
  const box = root.querySelector('.search-container');
  const input = root.querySelector('#searchInput');
  const foreground = root.querySelector('.foreground');
  const trending = root.querySelector('.trending-search-container');
  const divider = root.querySelector('.cmp-bns-search__input-controls .divider');
  const clear = root.querySelector('#searchClose');
  if (!box || !input) return;
  const controls = () => {
    const filled = !!input.value;
    if (divider) divider.style.visibility = filled ? 'visible' : 'hidden';
    if (clear) {
      clear.style.display = filled ? 'flex' : 'none';
      clear.style.pointerEvents = filled ? 'auto' : 'none';
    }
  };
  const setPanel = (open) => {
    foreground?.classList.toggle('foreground-hide', !open);
    trending?.classList.toggle('trending-hide', !open);
  };
  input.addEventListener('focus', () => { setPanel(true); controls(); });
  input.addEventListener('input', controls);
  clear?.addEventListener('click', () => { input.value = ''; controls(); input.focus(); });
  document.addEventListener('mousedown', (e) => { if (!box.contains(e.target)) setPanel(false); });
  box.querySelector('form')?.addEventListener('submit', (e) => { e.preventDefault(); search(input.value.trim()); });
  root.querySelectorAll('.trending-search-container a.list-item, .cmp-modal-mobile-search-trending-list-item').forEach((a) => {
    a.addEventListener('click', () => search(a.textContent.trim()));
  });
}

function initMobile(root) {
  const header = root.querySelector('.compass-header');
  const toggle = root.querySelector('#toggleMobileNav');
  toggle?.addEventListener('click', () => {
    const open = toggle.getAttribute('aria-expanded') !== 'true';
    toggle.setAttribute('aria-expanded', open ? 'true' : 'false');
    header?.classList.toggle('active', open);
  });
  const trigger = root.querySelector('#mobileSearchTrigger');
  const modal = root.querySelector('#searchModal');
  const setSearch = (open) => {
    document.body.classList.toggle('mobile-search-modal-active', open);
    header?.classList.toggle('active', open);
    header?.classList.toggle('search-active', open);
    root.querySelector('.mobile-header')?.classList.toggle('mobile-header-hide', open);
    root.querySelector('div#search')?.classList.toggle('search-hide', !open);
    modal?.classList.toggle('mobile-search-hide', !open);
    if (open) root.querySelector('#header__search_mobile')?.focus();
  };
  trigger?.addEventListener('click', () => setSearch(true));
  root.querySelector('#searchModalClose')?.addEventListener('click', () => setSearch(false));
  root.querySelector('#mobileSearch')?.addEventListener('submit', (e) => {
    e.preventDefault();
    search(root.querySelector('#header__search_mobile')?.value.trim());
  });
}

/**
 * Binds the compass header interactions.
 * @param {Element} root the compass root (div.compass)
 */
export default function initCompass(root) {
  if (!root || root.dataset.compassInit) return;
  root.dataset.compassInit = 'true';
  initMenus(root);
  initSearch(root);
  initMobile(root);
}
